function WorldRenderer.prototype.syncTreePuzzle(self, flags)
    self:ensurePuzzleProps()
    local planted = flags.treePlanted == true
    local cut = flags.treeCut == true
    local taken = flags.saplingTaken == true
    self:setVisible(self.treeSapling, not planted and not cut and not taken)
    self:setVisible(self.treePit, not planted)
    self:setVisible(self.treeMain, planted and not cut)
    self:setVisible(self.treeMirror, planted and not cut)
    self:setVisible(self.stumpMain, cut)
    self:setVisible(self.stumpMirror, cut)
    if self.treeLadderDraw ~= nil then
        self.treeLadderDraw.visible = planted and not cut and self.activeFloor == 0
    end
end
function WorldRenderer.prototype.syncBarrel(self, dt, down, left)
    self:ensurePuzzleProps()
    if self.barrelSp == nil then
        return
    end
    if not down then
        self.barrelT = 0
        self.barrelSp.angle = 0
        self.barrelSp.position = Vec2(1900, FLOOR_TOPS[2])
        return
    end
    if self.barrelLeft ~= left then
        self.barrelLeft = left
        self.barrelT = 0
    end
    if self.barrelT < 1 then
        self.barrelT = Math:min(1, self.barrelT + dt * 3)
        local e = 1 - (1 - self.barrelT) * (1 - self.barrelT)
        self.barrelSp.angle = (left and -1 or 1) * 90 * e
        self.barrelSp.position = Vec2(1900 + (left and -1 or 1) * 40 * e, FLOOR_TOPS[2] + 6 * e)
    end
end
