function WorldRenderer.prototype.updatePortals(self, player, state, dt)
    do
        local i = 0
        while i < #self.portalNodes do
            local rec = self.portalNodes[i + 1]
            local unlocked = rec.gateId == nil or state.openedGates[rec.gateId] == true
            local want = unlocked and rec.floor == self.sceneBand and Math:abs(player.body.x - rec.x) < 280
            rec.fade = rec.fade + ((want and 1 or 0) - rec.fade) * Math:min(1, dt * 8)
            if rec.fade < 0.005 then
                rec.fade = 0
            end
            rec.node.visible = rec.fade > 0.02
            rec.node.opacity = rec.fade
            i = i + 1
        end
    end
end
