function WorldRenderer.prototype.syncBossWaveSprites(self, enemies)
    if not self.bossWaveChecked then
        self.bossWaveChecked = true
        self.bossWaveTex = self:loadTex("assets/effects/slash_blue.png")
    end
    local tex = self.bossWaveTex
    if tex == nil then
        return false
    end
    local waves = enemies.waves
    local frames = Math:max(
        1,
        Math:floor(tex.width / 64)
    )
    while #self.bossWaveSprites > #waves do
        local sp = self.bossWaveSprites:pop()
        if sp ~= nil then
            sp:removeFromParent()
        end
    end
    while #self.bossWaveSprites < #waves do
        local created = Sprite(
            tex,
            Rect(
                Math:floor(frames / 2) * 64,
                0,
                64,
                64
            )
        )
        if created == nil then
            return false
        end
        created.filter = "Point"
        created:addTo(self.waveSpriteRoot)
        self.bossWaveSprites:push(created)
    end
    local k = 92 / 64
    do
        local i = 0
        while i < #self.bossWaveSprites do
            local sp = self.bossWaveSprites[i + 1]
            local wv = waves[i + 1]
            sp.position = Vec2(wv.x, wv.y + 20)
            sp.scaleX = (wv.dir >= 0 and 1 or -1) * k
            sp.scaleY = k
            sp.opacity = wv.life < 0.4 and Math:floor(255 * (wv.life / 0.4)) or 255
            i = i + 1
        end
    end
    return true
end
function WorldRenderer.prototype.drawArrow(self, d, x, y, vx, vy)
    local lenRaw = Math:sqrt(vx * vx + vy * vy)
    local len = lenRaw > 0.0001 and lenRaw or 1
    local ux = vx / len
    local uy = vy / len
    seg(
        d,
        x - ux * 12,
        y - uy * 12,
        x + ux * 6,
        y + uy * 6,
        2.2,
        ink(196, 188, 168, 235)
    )
    dot(
        d,
        x + ux * 7,
        y + uy * 7,
        2.4,
        ink(244, 240, 226, 255)
    )
end
