function WorldRenderer.prototype.updateHeroSprite(self, x, y, facing, pose, t, phaseIndex, visible, dt)
    local sp = self.heroSprite
    local f = self.heroFxDraw
    f:clear()
    self:updateGhosts(dt)
    if not visible then
        if sp ~= nil then
            sp.visible = false
        end
        self.heroFrames:hideAll()
        return
    end
    local fr = self.heroFrames:pick(pose, t)
    if fr ~= nil then
        if sp ~= nil then
            sp.visible = false
        end
        self.heroFrames:hideAll()
        fr.sp.visible = true
        local bobF = 0
        if pose == "jump" then
            bobF = 2
        elseif pose == "fall" then
            bobF = -2
        end
        fr.sp.position = Vec2(x, y + bobF)
        fr.sp.scaleX = fr.scale * facing * (HERO_FRAMES_FACE_RIGHT and 1 or -1)
        fr.sp.scaleY = fr.scale
        if self.ghostCd <= 0 and (pose == "dash" or pose == "jump" or pose == "fall") then
            self:spawnGhost(fr, x, y + bobF, facing)
            self.ghostCd = GHOST_INTERVAL
        end
        self:drawHeroFx(
            f,
            x,
            y,
            facing,
            pose,
            t,
            phaseIndex,
            0
        )
        return
    end
    self.heroFrames:hideAll()
    if sp == nil then
        self:drawHeroFx(
            f,
            x,
            y,
            facing,
            pose,
            t,
            phaseIndex,
            0
        )
        return
    end
    sp.visible = true
    local bob = 0
    if pose == "idle" then
        bob = Math:sin(t * 2) * 1.6
    elseif pose == "run" then
        bob = -Math:abs(Math:sin(t * 12)) * 2.2
    elseif pose == "jump" then
        bob = 2.5
    elseif pose == "fall" then
        bob = -1.5
    end
    sp.position = Vec2(x, y + bob)
    sp.scaleX = self.heroScale * facing
    sp.scaleY = self.heroScale
    self:drawHeroFx(
        f,
        x,
        y,
        facing,
        pose,
        t,
        phaseIndex,
        bob
    )
end
function WorldRenderer.prototype.drawHeroFx(self, f, x, y, _facing, pose, _t, _phaseIndex, _bob)
    if pose == "hurt" then
        dot(
