            y + 46,
            26,
            ink(220, 70, 60, 160),
            0.5
        )
    end
end
function WorldRenderer.prototype.updateGhosts(self, dt)
    if self.ghostCd > 0 then
        self.ghostCd = self.ghostCd - dt
    end
    local i = #self.ghosts - 1
    while i >= 0 do
        local g = self.ghosts[i + 1]
        g.t = g.t + dt
        if g.t >= g.dur then
            g.sp:removeFromParent()
            self.ghosts:splice(i, 1)
        else
            g.sp.opacity = GHOST_ALPHA * (1 - g.t / g.dur)
        end
        i = i - 1
    end
end
function WorldRenderer.prototype.spawnGhost(self, fr, x, y, facing)
    if #self.ghosts >= GHOST_MAX then
        return
    end
    local tex = fr.sp.texture
    if tex == nil then
        return
    end
    local sp = Sprite(tex)
    if sp == nil then
        return
    end
    sp.anchor = Vec2(0.5, 0)
    sp.position = Vec2(x - facing * GHOST_OFFSET, y)
    sp.scaleX = fr.scale * facing * (HERO_FRAMES_FACE_RIGHT and 1 or -1)
    sp.scaleY = fr.scale
    sp.color = Color(GHOST_TINT_R, GHOST_TINT_G, GHOST_TINT_B, 255)
    sp.opacity = GHOST_ALPHA
    sp:addTo(self.ghostRoot)
    self.ghosts:push({sp = sp, t = 0, dur = GHOST_DUR})
end
function WorldRenderer.prototype.heroPose(self, p)
    if p.onLadder then
        return "ladder"
    end
    local a = p.anim
    if a == "wallslide" then
        return "cling"
    end
    if a == "climb" then
        return "ladder"
    end
    if a == "attack" then
        local idx = p.attackIndex
        return idx <= 0 and "attack1" or (idx == 1 and "attack2" or (idx == 2 and "attack3" or "heavy"))
    end
    if a == "land" then
        return "idle"
    end
    return a
end
return ____exports
